public void put(String entityTypeId, Entity entity) {
    CombinedEntityCache entityCache = caches.get();
    if (entityCache != null) {
      entityCache.put(entity);
      LOG.trace(
          "Added dehydrated row [{}] from entity {} to the L1 cache",
          entity.getIdValue(),
          entityTypeId);
    }
  }

