public static void runExample(
      AdWordsServicesInterface adWordsServices, AdWordsSession session, String reportFile)
      throws ReportDownloadResponseException, ReportException, IOException  {
    // Create query.
    ReportQuery query =
        new ReportQuery.Builder()
            .fields(
                "CampaignId",
                "AdGroupId",
                "Id",
                "Criteria",
                "CriteriaType",
                "Impressions",
                "Clicks",
                "Cost")
            .from(ReportDefinitionReportType.CRITERIA_PERFORMANCE_REPORT)
            .where("Status").in("ENABLED", "PAUSED")
            .during(ReportDefinitionDateRangeType.LAST_7_DAYS)
            .build();

    // Optional: Set the reporting configuration of the session to suppress header, column name, or
    // summary rows in the report output. You can also configure this via your ads.properties
    // configuration file. See AdWordsSession.Builder.from(Configuration) for details.
    // In addition, you can set whether you want to explicitly include or exclude zero impression
    // rows.
    ReportingConfiguration reportingConfiguration =
        new ReportingConfiguration.Builder()
            .skipReportHeader(false)
            .skipColumnHeader(false)
            .skipReportSummary(false)
            // Set to false to exclude rows with zero impressions.
            .includeZeroImpressions(true)
            .build();
    session.setReportingConfiguration(reportingConfiguration);

    ReportDownloaderInterface reportDownloader =
        adWordsServices.getUtility(session, ReportDownloaderInterface.class);

    // Set the property api.adwords.reportDownloadTimeout or call
    // ReportDownloader.setReportDownloadTimeout to set a timeout (in milliseconds)
    // for CONNECT and READ in report downloads.
    ReportDownloadResponse response =
        reportDownloader.downloadReport(query.toString(), DownloadFormat.CSV);
    response.saveToFile(reportFile);

    System.out.printf("Report successfully downloaded to: %s%n", reportFile);
  }

public ServiceFuture<NetworkInterfaceInner> updateTagsAsync(String resourceGroupName, String networkInterfaceName, Map<String, String> tags, final ServiceCallback<NetworkInterfaceInner> serviceCallback) {
        return ServiceFuture.fromResponse(updateTagsWithServiceResponseAsync(resourceGroupName, networkInterfaceName, tags), serviceCallback);
    }

public Observable<ServiceResponseWithHeaders<ImmutabilityPolicyInner, BlobContainersExtendImmutabilityPolicyHeaders>> extendImmutabilityPolicyWithServiceResponseAsync(String resourceGroupName, String accountName, String containerName, String ifMatch, int immutabilityPeriodSinceCreationInDays) {
        if (resourceGroupName == null) {
            throw new IllegalArgumentException("Parameter resourceGroupName is required and cannot be null.");
        }
        if (accountName == null) {
            throw new IllegalArgumentException("Parameter accountName is required and cannot be null.");
        }
        if (containerName == null) {
            throw new IllegalArgumentException("Parameter containerName is required and cannot be null.");
        }
        if (this.client.subscriptionId() == null) {
            throw new IllegalArgumentException("Parameter this.client.subscriptionId() is required and cannot be null.");
        }
        if (this.client.apiVersion() == null) {
            throw new IllegalArgumentException("Parameter this.client.apiVersion() is required and cannot be null.");
        }
        if (ifMatch == null) {
            throw new IllegalArgumentException("Parameter ifMatch is required and cannot be null.");
        }
        ImmutabilityPolicyInner parameters = new ImmutabilityPolicyInner();
        parameters.withImmutabilityPeriodSinceCreationInDays(immutabilityPeriodSinceCreationInDays);
        return service.extendImmutabilityPolicy(resourceGroupName, accountName, containerName, this.client.subscriptionId(), this.client.apiVersion(), ifMatch, this.client.acceptLanguage(), parameters, this.client.userAgent())
            .flatMap(new Func1<Response<ResponseBody>, Observable<ServiceResponseWithHeaders<ImmutabilityPolicyInner, BlobContainersExtendImmutabilityPolicyHeaders>>>() {
                @Override
                public Observable<ServiceResponseWithHeaders<ImmutabilityPolicyInner, BlobContainersExtendImmutabilityPolicyHeaders>> call(Response<ResponseBody> response) {
                    try {
                        ServiceResponseWithHeaders<ImmutabilityPolicyInner, BlobContainersExtendImmutabilityPolicyHeaders> clientResponse = extendImmutabilityPolicyDelegate(response);
                        return Observable.just(clientResponse);
                    } catch (Throwable t) {
                        return Observable.error(t);
                    }
                }
            });
    }

private Class<?> getTemplateClass() {
        String fqName = getTargetPackage() + "." + getName();
        try {
            mTemplateClass = getCompiler().loadClass(fqName);
        }
        catch (ClassNotFoundException nx) {
            try {
                mTemplateClass = getCompiler().loadClass(getName());  // Try standard path as a last resort
            }
            catch (ClassNotFoundException nx2) {
                return null;
            }
        }
        return mTemplateClass;
    }

private List<CmsResource> searchResources(I_CmsReport report, CmsObject cmsObject) {

        report.println(
            Messages.get().container(Messages.RPT_SOURCESEARCH_START_COLLECTING_FILES_TO_SEARCH_IN_0),
            I_CmsReport.FORMAT_HEADLINE);

        List<CmsResource> resources = new ArrayList<CmsResource>();
        if (m_settings.isSolrSearch()) {
            CmsSolrIndex index = OpenCms.getSearchManager().getIndexSolr(m_settings.getSource());
            if (index != null) {
                CmsSolrQuery query = new CmsSolrQuery(
                    null,
                    CmsRequestUtil.createParameterMap(m_settings.getQuery() + "&fl=path,type"));
                query.setSearchRoots(m_settings.getPaths());
                if ((m_settings.getTypesArray() != null) && (m_settings.getTypesArray().length > 0)) {
                    query.setResourceTypes(m_settings.getTypesArray());
                }
                query.setRows(new Integer(MAX_PROCESSED_SOLR_RESULTS));
                query.ensureParameters();
                try {
                    resources.addAll(
                        index.search(cmsObject, query, true, null, false, null, MAX_PROCESSED_SOLR_RESULTS));
                } catch (CmsSearchException e) {
                    LOG.error(e.getMessage(), e);
                }
            }
        } else {
            CmsResourceFilter filter = CmsResourceFilter.ALL.addRequireFile().addExcludeState(
                CmsResource.STATE_DELETED).addRequireTimerange().addRequireVisible();
            if ((m_settings.getTypesArray() != null) && (m_settings.getTypesArray().length > 0)) {
                for (String resTypeName : m_settings.getTypesArray()) {
                    try {
                        I_CmsResourceType type = OpenCms.getResourceManager().getResourceType(resTypeName);
                        filter = filter.addRequireType(type);
                    } catch (CmsLoaderException e) {
                        // noop
                    } catch (NullPointerException e) {
                        // noop
                    }
                }
            }

            // iterate over all selected paths
            Iterator<String> iterPaths = m_settings.getPaths().iterator();
            while (iterPaths.hasNext()) {
                String path = iterPaths.next();
                try {
                    // only read resources which are files and not deleted, which are in the current time range window and where the current
                    // user has the sufficient permissions to read them
                    List<CmsResource> tmpResources = getCms().readResources(path, filter);
                    if ((tmpResources != null) && !tmpResources.isEmpty()) {
                        resources.addAll(tmpResources);
                    }
                } catch (CmsException e) {
                    // an error occured
                    LOG.error(Messages.get().container(Messages.RPT_SOURCESEARCH_ERROR_READING_RESOURCES_1, path), e);
                    report.println(
                        Messages.get().container(Messages.RPT_SOURCESEARCH_ERROR_READING_RESOURCES_1, path),
                        I_CmsReport.FORMAT_ERROR);
                }
            }
        }
        return resources;
    }

private int calculateSexCode(Person.Sex sex) {
		return SEX_FIELDS[baseProducer.randomInt(SEX_FIELDS.length - 1)] + (sex == Person.Sex.MALE ? 1 : 0);
	}

public Point3d calculate3DCoordinates3(Point3d aPoint, Point3d bPoint, Point3d cPoint, Point3d dPoint, double length) {
        //logger.debug("3DCoordinates3");
        Vector3d bc = new Vector3d(bPoint);
        bc.sub(cPoint);
        Vector3d dc = new Vector3d(dPoint);
        dc.sub(cPoint);
        Vector3d ca = new Vector3d(cPoint);
        ca.sub(aPoint);

        Vector3d n1 = new Vector3d();
        Vector3d n2 = new Vector3d();

        n1.cross(bc, dc);
        n1.normalize();
        n1.scale(length);

        Vector3d ax = new Vector3d(aPoint);
        ax.add(n1);
        ax.sub(aPoint);

        Vector3d ax2 = new Vector3d(aPoint);
        ax2.add(n2);
        ax2.sub(aPoint);

        Point3d point = new Point3d(aPoint);

        double dotProduct = ca.dot(ax);
        double angle = Math.acos((dotProduct) / (ax.length() * ca.length()));

        if (angle < 1.5) {
            n2.cross(dc, bc);
            n2.normalize();
            n2.scale(length);
            point.add(n2);
        } else {
            point.add(n1);
        }

        bc = null;
        dc = null;
        ca = null;
        n1 = null;
        n2 = null;
        return point;
    }

protected boolean isParam(ExpressionNode expr)
  {
  	while(null != expr)
  	{
  		if(expr instanceof ElemTemplateElement)
  			break;
  		expr = expr.exprGetParent();
  	}
  	if(null != expr)
  	{
  		ElemTemplateElement ete = (ElemTemplateElement)expr;
  		while(null != ete)
  		{
  			int type = ete.getXSLToken();
  			switch(type)
  			{
  				case Constants.ELEMNAME_PARAMVARIABLE:
  					return true;
  				case Constants.ELEMNAME_TEMPLATE:
  				case Constants.ELEMNAME_STYLESHEET:
  					return false;
  			}
  			ete = ete.getParentElem();
  		}
  	}
  	return false;

  }

