public static String join( Collection col, char sep )
	{
		if( col.isEmpty() )
		{
			return "";
		}
		StringBuffer buffer = new StringBuffer();
		boolean first = true; 
		for (Object o : col)
		{
			if( first )
			{
				first = false;
			}
			else
			{
				buffer.append( sep );
			}
			buffer.append( o.toString() );
		}
		return buffer.toString();
	}

@Override
    public AuthenticationStatus redirect(String location) {
        try {
            response.sendRedirect(response.encodeURL(location));
            response.setStatus(HttpServletResponse.SC_FOUND);
        } catch (IOException e) {
            // TODO: Determine if this needs a serviceability message
        }
        return AuthenticationStatus.SEND_CONTINUE;
    }

