private COFFFileHeader reloadCOFFFileHeader(PESignature pesig,
            MemoryMappedPE mmBytes, PEData data) throws IOException {
        // coff header starts right after the PE signature
        long offset = pesig.getOffset() + PESignature.PE_SIG.length;
        /* read bytes, size is fixed anyway */
        long sizeOfHeaders = data.getOptionalHeader().get(
                WindowsEntryKey.SIZE_OF_HEADERS);
        logger.debug("SizeOfHeaders: " + sizeOfHeaders);
        // virtual end of header mapping marked by VA of first section
        long vEnd = data.getSectionTable().getSectionHeader(1)
                .getAlignedVirtualAddress() - 1;
        // virtual start of headers TODO test
        long vStart = vEnd - sizeOfHeaders;
        long sliceStart = vStart + PESignature.PE_SIG.length;
        logger.debug("reading coff at start: " + sliceStart);
        byte[] headerbytes = mmBytes.slice(sliceStart, sliceStart
                + COFFFileHeader.HEADER_SIZE);
        // construct header
        return COFFFileHeader.newInstance(headerbytes, offset);
    }

public final void push(int value)
  {

    int ff = m_firstFree;

    if ((ff + 1) >= m_mapSize)
    {
      if (null == m_map)
      {
        m_map = new int[m_blocksize];
        m_mapSize = m_blocksize;
      }
      else
      {
        m_mapSize += m_blocksize;

        int newMap[] = new int[m_mapSize];

        System.arraycopy(m_map, 0, newMap, 0, ff + 1);

        m_map = newMap;
      }
    }

    m_map[ff] = value;

    ff++;

    m_firstFree = ff;
  }

public static void fireLocationChange(final Item rootItem, final String oldFullName) {
        String prefix = rootItem.getParent().getFullName();
        if (!prefix.isEmpty()) {
            prefix += '/';
        }
        final String newFullName = rootItem.getFullName();
        assert newFullName.startsWith(prefix);
        int prefixS = prefix.length();
        if (oldFullName.startsWith(prefix) && oldFullName.indexOf('/', prefixS) == -1) {
            final String oldName = oldFullName.substring(prefixS);
            final String newName = rootItem.getName();
            assert newName.equals(newFullName.substring(prefixS));
            forAll(new Function<ItemListener, Void>() {
                @Override public Void apply(ItemListener l) {
                    l.onRenamed(rootItem, oldName, newName);
                    return null;
                }
            });
        }
        forAll(new Function<ItemListener, Void>() {
            @Override public Void apply(ItemListener l) {
                l.onLocationChanged(rootItem, oldFullName, newFullName);
                return null;
            }
        });
        if (rootItem instanceof ItemGroup) {
            for (final Item child : Items.allItems(ACL.SYSTEM, (ItemGroup)rootItem, Item.class)) {
                final String childNew = child.getFullName();
                assert childNew.startsWith(newFullName);
                assert childNew.charAt(newFullName.length()) == '/';
                final String childOld = oldFullName + childNew.substring(newFullName.length());
                forAll(new Function<ItemListener, Void>() {
                    @Override public Void apply(ItemListener l) {
                        l.onLocationChanged(child, childOld, childNew);
                        return null;
                    }
                });
            }
        }
    }

public M join()
    {
        if (threadMap.isEmpty())
        {
            throw new IllegalStateException("threads are already interrupted");
        }
        Thread currentThread = Thread.currentThread();
        Semaphore currentSemaphore = semaphoreMap.get(currentThread);
        if (currentSemaphore == null)
        {
            throw new IllegalStateException("Current thread is not workflow thread");
        }
        stopSemaphore.release();
        parallelSet.remove(getCurrentKey());
        return doJoin();
    }

static void writeTrampoline(ByteBuffer buf, long target) {
        // Jmp.
        buf.put((byte) 0xFF);

        // ModM (RIP addressing).
        buf.put((byte) 0x25);
        // Offset (zero).
        buf.putInt(0);
        // Absolute address.
        buf.putLong(target);
    }

private void readJSR303Annotations(UIComponent component) {
		coreExpression = ELTools.getCoreValueExpression(component);
		Annotation[] annotations = ELTools.readAnnotations(component);
		if (null != annotations) {
			for (Annotation a : annotations) {
				if (a instanceof Max) {
					long maximum = ((Max) a).value();
					max = maximum;
					hasMax = true;
				} else if (a instanceof Min) {
					long minimum = ((Min) a).value();
					hasMin = true;
					min = minimum;
				} else if (a instanceof Size) {
					maxSize = ((Size) a).max();
					hasMaxSize = maxSize > 0;
					minSize = ((Size) a).min();
					hasMinSize = minSize > 0;
				} else if (a instanceof NotNull) {
					isRequired = true;
				}
			}
		}

		clazz = ELTools.getType(component);
		if ((clazz == Integer.class) || (clazz == int.class)
				|| (clazz == Byte.class) || (clazz == byte.class)
				|| (clazz == Short.class) || (clazz == short.class)
				|| (clazz == Long.class) || (clazz == long.class)) {
			isInteger = true;
			isNumeric = true;
		} else if ((clazz == Double.class) || (clazz == double.class)
				|| (clazz == Float.class) || (clazz == float.class)) {
			isFloat = true;
			isNumeric = true;
		} else if ((clazz==Date.class) || (clazz==java.util.Date.class)) {
			isDate=true;
		}
	}

