            throw new SdkClientException("Invalid argument passed to marshall(...)");
        }

        try {
            protocolMarshaller.marshall(warning.getCode(), CODE_BINDING);
            protocolMarshaller.marshall(warning.getMessage(), MESSAGE_BINDING);
