TimeVal time_diff(final TimeVal before, final TimeVal after_t) {
	final double bef_d = before.tv_sec + (double) before.tv_usec / 1000000;
	final double aft_d = after_t.tv_sec + (double) after_t.tv_usec / 1000000;
	final double diff_d = aft_d - bef_d;

	final TimeVal result = new TimeVal();
	result.tv_sec = (int) diff_d;
	result.tv_usec = (int) ((diff_d - result.tv_sec) * 1000000);
	return result;
    }

public static int indexOf(String S, char[] chars, int start) {
		int Slen=S.length();
		int clen=chars.length;
		for(int c=start;c<Slen;c++) {
			char ch=S.charAt(c);
			for(int d=0;d<clen;d++) if(ch==chars[d]) return c;
		}
		return -1;
	}

public static String formatPropertyName(final String value)
    {
        String formattedValue = Generators.toLowerFirstChar(value);

        if (ValidationUtil.isJavaKeyword(formattedValue))
        {
            final String keywordAppendToken = System.getProperty(SbeTool.KEYWORD_APPEND_TOKEN);
            if (null == keywordAppendToken)
            {
                throw new IllegalStateException(
                    "Invalid property name='" + formattedValue +
                    "' please correct the schema or consider setting system property: " + SbeTool.KEYWORD_APPEND_TOKEN);
            }

            formattedValue += keywordAppendToken;
        }

        return formattedValue;
    }

public synchronized ValidationMessage[] validate(
            int type, String prefix, String uri, PageData page) {
        try {
            this.tlvType = type;
            this.uri = uri;
            // initialize
            messageVector = new Vector();

            // save the prefix
            this.prefix = prefix;

            // parse parameters if necessary
            try {
                if (config == null) {
                    configure((String) getInitParameters().get(EXP_ATT_PARAM));
                }
            } catch (NoSuchElementException ex) {
                // parsing error
                return vmFromString(
                        Resources.getMessage("TLV_PARAMETER_ERROR",
                                EXP_ATT_PARAM));
            }

            // get a handler
            DefaultHandler h = getHandler();

            // parse the page
            XMLReader xmlReader = XmlUtil.newXMLReader(null);
            xmlReader.setContentHandler(h);
            InputStream inputStream = page.getInputStream();
            try {
                xmlReader.parse(new InputSource(inputStream));
            } finally {
                try {
                    inputStream.close();
                } catch (IOException e) {
                    // Suppressed.
                }
            }

            if (messageVector.size() == 0) {
                return null;
            } else {
                return vmFromVector(messageVector);
            }

        } catch (SAXException ex) {
            return vmFromString(ex.toString());
        } catch (IOException ex) {
            return vmFromString(ex.toString());
        } catch (ParserConfigurationException ex) {
            return vmFromString(ex.toString());
        }
    }

@SuppressWarnings("PMD.SimplifyBooleanReturns")
    private boolean differentAttributes(Method m1, Method m2) {
        if (m1.getAnnotationEntries().length > 0 || m2.getAnnotationEntries().length > 0) {
            return true;
        }
        int access1 = m1.getAccessFlags()
                & (Const.ACC_PRIVATE | Const.ACC_PROTECTED | Const.ACC_PUBLIC | Const.ACC_FINAL);
        int access2 = m2.getAccessFlags()
                & (Const.ACC_PRIVATE | Const.ACC_PROTECTED | Const.ACC_PUBLIC | Const.ACC_FINAL);


        m1.getAnnotationEntries();
        if (access1 != access2) {
            return true;
        }
        if (!thrownExceptions(m1).equals(thrownExceptions(m2))) {
            return false;
        }
        return false;
    }

