public static boolean containsLogFiles(File location) {
        if (location == null) {
            return false;
        }

        location = checkKnownType(location);

        if (isFile(location)) {
            try {
                // Is a WBL file.
                if (new OneFileBrowserImpl(location).getProcessId() != null) {
                    return true;
                }
            } catch (IllegalArgumentException ex) {
                // Fall through, can't use as a WBL file.
            }
            return false;
        }

        if (location.isDirectory()) {
            // Contains WBL files.
            LogRepositoryBrowserImpl browser = new LogRepositoryBrowserImpl(location, new String[] { location.getName() });
            if (browser.findNext((File) null, -1) != null) {
                return true;
            }

            // Its directories contain WBL files
            File[] wblDirs = location.listFiles(new FileFilter() {
                @Override
                public boolean accept(File pathname) {
                    return pathname.isDirectory() && new LogRepositoryBrowserImpl(pathname, new String[] { pathname.getName() }).findNext((File) null, -1) != null;
                }
            });
            if (wblDirs.length > 0) {
                return true;
            }
        }

        for (File file : new File[] {
                                      location,
                                      getChild(location, LogRepositoryBrowserImpl.DEFAULT_LOCATION),
                                      getChild(location, LogRepositoryBrowserImpl.TRACE_LOCATION) }) {
            // Contains Instance directories
            if (file.isDirectory()) {
                MainLogRepositoryBrowserImpl fileBrowser = new MainLogRepositoryBrowserImpl(file);
                if (fileBrowser.findByMillis(-1) != null) {
                    return true;
                }
            }
        }

        return false;
    }

@SuppressWarnings("unused")
    private void allocateDataChannel(int channelType, int channelIndex) {
        switch (channelType) {
        case NORMALS:
            m_normals = ByteBuffer.allocateDirect(
                    m_numVertices * 3 * SIZEOF_FLOAT);
            m_normals.order(ByteOrder.nativeOrder());
            break;
        case TANGENTS:
            m_tangents = ByteBuffer.allocateDirect(
                    m_numVertices * 3 * SIZEOF_FLOAT);
            m_tangents.order(ByteOrder.nativeOrder());
            break;
        case BITANGENTS:
            m_bitangents = ByteBuffer.allocateDirect(
                    m_numVertices * 3 * SIZEOF_FLOAT);
            m_bitangents.order(ByteOrder.nativeOrder());
            break;
        case COLORSET:
            m_colorsets[channelIndex] = ByteBuffer.allocateDirect(
                    m_numVertices * 4 * SIZEOF_FLOAT);
            m_colorsets[channelIndex].order(ByteOrder.nativeOrder());
            break;
        case TEXCOORDS_1D:
            m_numUVComponents[channelIndex] = 1;
            m_texcoords[channelIndex] = ByteBuffer.allocateDirect(
                    m_numVertices * 1 * SIZEOF_FLOAT);
            m_texcoords[channelIndex].order(ByteOrder.nativeOrder());
            break;
        case TEXCOORDS_2D:
            m_numUVComponents[channelIndex] = 2;
            m_texcoords[channelIndex] = ByteBuffer.allocateDirect(
                    m_numVertices * 2 * SIZEOF_FLOAT);
            m_texcoords[channelIndex].order(ByteOrder.nativeOrder());
            break;
        case TEXCOORDS_3D:
            m_numUVComponents[channelIndex] = 3;
            m_texcoords[channelIndex] = ByteBuffer.allocateDirect(
                    m_numVertices * 3 * SIZEOF_FLOAT);
            m_texcoords[channelIndex].order(ByteOrder.nativeOrder());
            break;
        default:
            throw new IllegalArgumentException("unsupported channel type");
        }
    }

