public static QueryException fromThrowable(String message, Throwable cause) {
    return (cause instanceof QueryException && Objects.equals(message, cause.getMessage()))
                   ? (QueryException) cause
                   : new QueryException(message, cause);
  }

private List<Entry<V>> filterEntryList(List<Entry<V>> entryList, long minScn, long maxScn) {
    List<Entry<V>> result = new ArrayList<Entry<V>>(entryList.size());
    for (Entry<V> e : entryList) {
      if (minScn <= e.getMinScn() && e.getMaxScn() <= maxScn) {
        result.add(e);
      }
    }

    return result;
  }

