                        setLegendItemFont(new Font("Dialog", Font.PLAIN, 9)).
                        setBackgroundPaint(Color.white).
                        setGridPaint(Color.gray).
                        setInsertLast(false);
            default:
                return this;
        }
    }

public I_CmsHtmlConverter addHtmlConverter(String name, String className) throws CmsConfigurationException {

        // check if new conversion option can still be added
        if (m_frozen) {
            throw new CmsConfigurationException(Messages.get().container(Messages.ERR_NO_CONFIG_AFTER_STARTUP_0));
        }

        Class<?> classClazz;
        // init class for content converter
        try {
            classClazz = Class.forName(className);
        } catch (ClassNotFoundException e) {
            LOG.error(Messages.get().getBundle().key(Messages.LOG_HTML_CONVERTER_CLASS_NOT_FOUND_1, className), e);
            return null;
        }

        I_CmsHtmlConverter converter;
        try {
            converter = (I_CmsHtmlConverter)classClazz.newInstance();
        } catch (InstantiationException e) {
            throw new CmsConfigurationException(
                Messages.get().container(Messages.ERR_INVALID_HTMLCONVERTER_NAME_1, className));
        } catch (IllegalAccessException e) {
            throw new CmsConfigurationException(
                Messages.get().container(Messages.ERR_INVALID_HTMLCONVERTER_NAME_1, className));
        } catch (ClassCastException e) {
            throw new CmsConfigurationException(
                Messages.get().container(Messages.ERR_INVALID_HTMLCONVERTER_NAME_1, className));
        }

        if (CmsLog.INIT.isInfoEnabled()) {
            CmsLog.INIT.info(Messages.get().getBundle().key(Messages.INIT_ADD_HTML_CONVERTER_CLASS_2, className, name));
        }

        m_configuredHtmlConverters.add(new CmsHtmlConverterOption(name, className));
        return converter;
    }

static ImmutableList<GroupResult> groupActiveFindingsWithSource(SourceName sourceName) {
    try (SecurityCenterClient client = SecurityCenterClient.create()) {
      // SourceName sourceName = SourceName.of(/*organization=*/"123234324",/*source=*/
      // "423432321");

      GroupFindingsRequest.Builder request =
          GroupFindingsRequest.newBuilder()
              .setParent(sourceName.toString())
              .setGroupBy("category")
              .setFilter("state=\"ACTIVE\"");

      // Call the API.
      GroupFindingsPagedResponse response = client.groupFindings(request.build());

      // This creates one list for all findings.  If your organization has a large number of
      // findings
      // this can cause out of memory issues.  You can process them batches by returning
      // the Iterable returned response.iterateAll() directly.
      ImmutableList<GroupResult> results = ImmutableList.copyOf(response.iterateAll());
      System.out.println("Findings:");
      System.out.println(results);
      return results;
    } catch (IOException e) {
      throw new RuntimeException("Couldn't create client.", e);
    }
  }

public static boolean endsWithPunc(String str) {
		if (str.endsWith(".") || str.endsWith("?") || str.endsWith("!") ||
			    str.endsWith(",") || str.endsWith(":") || str.endsWith("\"") || 
			    str.endsWith("'") || str.endsWith("''") || str.endsWith(";")) {
		    return true;
		}

		return false;
    }

public static String decode(CharSequence chars) {
		CharDecoder decoder = new CharDecoder();

		chars.chars().forEach(decoder::decode);
		return decoder.getDecoded();
	}

