public static String getMediaTypeForFileSuffix(String fileName) {
    String mediaType = "application/octet-stream"; // default
    if (fileName != null) {
      fileName = fileName.toLowerCase();
      if (fileName.endsWith(".png")) {
        mediaType = "image/png";
      } else if (fileName.endsWith(".svg")) {
        mediaType = "image/svg+xml";
      } else if (fileName.endsWith(".jpg") || fileName.endsWith(".jpeg")) {
        mediaType = "image/jpeg";
      } else if (fileName.endsWith(".gif")) {
        mediaType = "image/gif";
      } else if (fileName.endsWith(".bmp")) {
        mediaType = "image/bmp";
      }
    }
    return mediaType;
  }

@SuppressWarnings({ "rawtypes", "unchecked" })
	private Object adjustablePartsCloned(Object original) {
		if (original instanceof NamedList) {
			NamedList<Object> newObject = new SimpleOrderedMap();
			NamedList<Object> originalObject = (NamedList<Object>) original;
			for (int i = 0; i < originalObject.size(); i++) {
				newObject.add(originalObject.getName(i), adjustablePartsCloned(originalObject.getVal(i)));
			}
			return newObject;
		} else if (original instanceof ArrayList) {
			ArrayList<Object> newObject = new ArrayList<>();
			ArrayList<Object> originalObject = (ArrayList<Object>) original;
			for (int i = 0; i < originalObject.size(); i++) {
				newObject.add(adjustablePartsCloned(originalObject.get(i)));
			}
			return newObject;
		} else if (original instanceof Integer) {
			return original;
		}
		return original;
	}

private String getUserName(TOpenSessionReq req) throws HiveSQLException {
    String userName = null;
    // Kerberos
    if (isKerberosAuthMode()) {
      userName = hiveAuthFactory.getRemoteUser();
    }
    // Except kerberos, NOSASL
    if (userName == null) {
      userName = TSetIpAddressProcessor.getUserName();
    }
    // Http transport mode.
    // We set the thread local username, in ThriftHttpServlet.
    if (cliService.getHiveConf().getVar(
        ConfVars.HIVE_SERVER2_TRANSPORT_MODE).equalsIgnoreCase("http")) {
      userName = SessionManager.getUserName();
    }
    if (userName == null) {
      userName = req.getUsername();
    }

    userName = getShortName(userName);
    String effectiveClientUser = getProxyUser(userName, req.getConfiguration(), getIpAddress());
    LOG.debug("Client's username: " + effectiveClientUser);
    return effectiveClientUser;
  }

public final CheckedMemorySegment put(DataInput in, int offset, int length) throws IOException {
		if (offset >= 0 && offset < this.size && length >= 0 && offset <= this.size - length) {
			in.readFully(this.memory, this.offset + offset, length);
			return this;
		} else {
			throw new IndexOutOfBoundsException();
		}
	}

