private void findBestWithoutFirst(List<DatanodeDescriptor> listOfNodes,
      DatanodeDescriptor[] result) {

    readLock();
    try {
      for (int in2 = 0; in2 < listOfNodes.size(); in2++) {
        DatanodeDescriptor n2 = listOfNodes.get(in2);

        for (int in3 = in2 + 1; in3 < listOfNodes.size(); in3++) {
          DatanodeDescriptor n3 = listOfNodes.get(in3);
          if (n2.getNetworkLocation().equals(n3.getNetworkLocation())) {
            RackRingInfo rackInfo = racksMap.get(n2.getNetworkLocation());
            assert (rackInfo != null);
            final int rackSize = rackInfo.rackNodes.size();
            final Integer idN2 = rackInfo.findNode(n2);
            final Integer idN3 = rackInfo.findNode(n3);

            if (idN2 != null && idN3 != null) {
              int dist = (idN3 - idN2 + rackSize) % rackSize;
              if (dist >= machineWindow) {
                dist = rackSize - dist; // try n2 - n3
              }

              if (dist < machineWindow) {
                result[0] = null;
                result[1] = n2;
                result[2] = n3;
                return;
              }
            }
          }
        }
      }
    } finally {
      readUnlock();
    }
  }

PartitionReplica checkAndGetPrimaryReplicaOwner(int partitionId, int replicaIndex) {
        InternalPartitionImpl partition = partitionStateManager.getPartitionImpl(partitionId);
        PartitionReplica owner = partition.getOwnerReplicaOrNull();
        if (owner == null) {
            logger.info("Sync replica target is null, no need to sync -> partitionId=" + partitionId + ", replicaIndex="
                    + replicaIndex);
            return null;
        }

        PartitionReplica localReplica = PartitionReplica.from(nodeEngine.getLocalMember());
        if (owner.equals(localReplica)) {
            if (logger.isFinestEnabled()) {
                logger.finest("This node is now owner of partition, cannot sync replica -> partitionId=" + partitionId
                        + ", replicaIndex=" + replicaIndex + ", partition-info="
                        + partitionStateManager.getPartitionImpl(partitionId));
            }
            return null;
        }

        if (!partition.isOwnerOrBackup(localReplica)) {
            if (logger.isFinestEnabled()) {
                logger.finest("This node is not backup replica of partitionId=" + partitionId
                        + ", replicaIndex=" + replicaIndex + " anymore.");
            }
            return null;
        }
        return owner;
    }

