public static Character detectChar(String string, CharPredicate predicate)
    {
        int size = string.length();
        for (int i = 0; i < size; i++)
        {
            char character = string.charAt(i);
            if (predicate.accept(character))
            {
                return character;
            }
        }
        return null;
    }

public JSONObject getAudioMediaFromPlaceId(String place_id) throws Exception {

		List<SelectedColumn> selectFields = new Vector<SelectedColumn>();
		selectFields.add( new SelectedColumn(SelectedColumn.Type.INTEGER, "id") );
		selectFields.add( new SelectedColumn(SelectedColumn.Type.INTEGER, "place_id") );
		selectFields.add( new SelectedColumn(SelectedColumn.Type.STRING, "filename") );
		selectFields.add( new SelectedColumn(SelectedColumn.Type.STRING, "mimetype") );
		selectFields.add( new SelectedColumn(SelectedColumn.Type.STRING, "title") );

		PreparedStatement stmt = connection.prepareStatement(
				"SELECT id,place_id,filename,mimetype,title " +
				"FROM contributions " +
				"WHERE mimetype LIKE 'audio/%' AND place_id = ?;"
				);
		stmt.setInt(1, Integer.parseInt(place_id));

		JSONArray array = executeStatementToJson(stmt, selectFields);

		JSONObject result = new JSONObject();
		result.put("media", array);

		return result;
	}

public String getViewSelect(String htmlAttributes) {

        List<String> options = new ArrayList<String>();
        List<String> values = new ArrayList<String>();
        int selectedIndex = 0;

        // loop through the vectors and fill the result vectors
        Iterator<CmsWorkplaceView> i = OpenCms.getWorkplaceManager().getViews().iterator();
        int count = -1;
        String currentView = getSettings().getViewUri();
        if (CmsStringUtil.isNotEmpty(currentView)) {
            // remove possible parameters from current view
            int pos = currentView.indexOf('?');
            if (pos >= 0) {
                currentView = currentView.substring(0, pos);
            }
        }
        while (i.hasNext()) {
            CmsWorkplaceView view = i.next();
            if (getCms().existsResource(view.getUri(), CmsResourceFilter.ONLY_VISIBLE_NO_DELETED)) {
                count++;
                // ensure the current user has +v+r permissions on the view
                String loopLink = getJsp().link(view.getUri());
                String localizedKey = resolveMacros(view.getKey());
                options.add(localizedKey);
                values.add(loopLink);

                if (loopLink.equals(currentView)) {
                    selectedIndex = count;
                }
            }
        }

        return buildSelect(htmlAttributes, options, values, selectedIndex);
    }

public static boolean isSelfCall(JCTree tree) {
