public static Bucket openBucket(CouchbaseCluster cluster, String name, String password)
    {
        if (cluster == null)
        {
            throw new KunderaException("CouchbaseCluster object can't be null");
        }
        try
        {
            Bucket bucket;
            if (password != null && !password.trim().isEmpty())
            {
                bucket = cluster.openBucket(name, password);
            }
            else
            {
                bucket = cluster.openBucket(name);
            }
            LOGGER.debug("Bucket [" + name + "] is opened!");
            return bucket;
        }
        catch (CouchbaseException ex)
        {
            LOGGER.error("Not able to open bucket [" + name + "].", ex);
            throw new KunderaException("Not able to open bucket [" + name + "].", ex);
        }

    }

private void executeJoinRequest(JoinRequest joinRequest, Connection connection) {
        clusterServiceLock.lock();
        try {
            if (checkJoinRequest(joinRequest, connection)) {
                return;
            }

            if (!authenticate(joinRequest)) {
                return;
            }

            if (!validateJoinRequest(joinRequest, joinRequest.getAddress())) {
                return;
            }

            startJoinRequest(joinRequest.toMemberInfo());
        } finally {
            clusterServiceLock.unlock();
        }
    }

public static void runExample(
      AdWordsServicesInterface adWordsServices, AdWordsSession session, long adGroupId)
      throws IOException {
    // Get the MediaService.
    MediaServiceInterface mediaService = adWordsServices.get(session, MediaServiceInterface.class);

    // Get the AdGroupAdService.
    AdGroupAdServiceInterface adGroupAdService =
        adWordsServices.get(session, AdGroupAdServiceInterface.class);

    // Create a responsive display ad.
    ResponsiveDisplayAd responsiveDisplayAd = new ResponsiveDisplayAd();

    // This ad format does not allow the creation of an image using the
    // Image.data field. An image must first be created using the MediaService,
    // and Image.mediaId must be populated when creating the ad.
    long marketingImageMediaId = uploadImage(mediaService, "https://goo.gl/3b9Wfh");
    Image marketingImage = new Image();
    marketingImage.setMediaId(marketingImageMediaId);
    responsiveDisplayAd.setMarketingImage(marketingImage);

    responsiveDisplayAd.setShortHeadline("Travel");
    responsiveDisplayAd.setLongHeadline("Travel the World");
    responsiveDisplayAd.setDescription("Take to the air!");
    responsiveDisplayAd.setBusinessName("Interplanetary Cruises");
    responsiveDisplayAd.setFinalUrls(new String[] {"http://www.example.com/"});

    // Optional: Create a square marketing image using MediaService, and set it
    // to the ad.
    long squareMarketingImageMediaId = uploadImage(mediaService, "https://goo.gl/mtt54n");
    Image squareMarketingImage = new Image();
    squareMarketingImage.setMediaId(squareMarketingImageMediaId);
    responsiveDisplayAd.setSquareMarketingImage(squareMarketingImage);

    // Optional: set call to action text.
    responsiveDisplayAd.setCallToActionText("Shop Now");

    // Optional: Set dynamic display ad settings, composed of landscape logo
    // image, promotion text, and price prefix.
    DynamicSettings dynamicDisplayAdSettings = createDynamicDisplayAdSettings(mediaService);
    responsiveDisplayAd.setDynamicDisplayAdSettings(dynamicDisplayAdSettings);

    // Whitelisted accounts only: Set color settings using hexadecimal values.
    // Set allowFlexibleColor to false if you want your ads to render by always
    // using your colors strictly.
    /*
    responsiveDisplayAd.setMainColor("#0000ff");
    responsiveDisplayAd.setAccentColor("#ffff00");
    responsiveDisplayAd.setAllowFlexibleColor(false);
    */

    // Whitelisted accounts only: Set the format setting that the ad will be
    // served in.
    /*
    responsiveDisplayAd.setFormatSetting(
        com.google.api.ads.adwords.axis.v201809.cm.DisplayAdFormatSetting.NON_NATIVE);
    */

    // Create ad group ad for the responsive display ad.
    AdGroupAd adGroupAd = new AdGroupAd();
    adGroupAd.setAdGroupId(adGroupId);
    adGroupAd.setAd(responsiveDisplayAd);

    // Optional: set the status.
    adGroupAd.setStatus(AdGroupAdStatus.PAUSED);

    // Create the operation.
    AdGroupAdOperation adGroupAdOperation = new AdGroupAdOperation();
    adGroupAdOperation.setOperand(adGroupAd);
    adGroupAdOperation.setOperator(Operator.ADD);

    // Make the mutate request.
    AdGroupAdReturnValue result =
        adGroupAdService.mutate(new AdGroupAdOperation[] {adGroupAdOperation});

    // Display ads.
    Arrays.stream(result.getValue())
        .map(adGroupAdResult -> (ResponsiveDisplayAd) adGroupAdResult.getAd())
        .forEach(
            newAd ->
                System.out.printf(
                    "Responsive display ad with ID %d and short headline '%s' was added.%n",
                    newAd.getId(), newAd.getShortHeadline()));
  }

private void balance12(
    NodeStack     stack,
    GBSNode       bparent,         /* Parent of fringe balance point        */
    GBSNode       fpoint,          /* Fringe balance point                  */
    int           fpidx,           /* Index within stack of fpoint          */
    int           maxBal)          /* Maximum allowed fringe imbalance      */
  {
    /*
        k = 12,     2k-1 = 23,     k-1 = 11

                [A-B-C-D-E-F-G-H-I-J-K]              [11 children]

                       becomes:

                *-------F-------*
                |               |
             *--C--*         *--I--*
             |     |         |     |
           *-B     D-*     *-H     J-*
           |         |     |         |
           A         E     G         K

  --------------------------------------------------------

                *-------F-------*
                |               |
             *--C--*         *--I--*
             |     |         |     |
           *-B     D-*     *-H     J-*          [14 children]
           |         |     |         |
           A         E     G         K - L-M-N-O-P-Q-R-S-T-U-V-W


                       becomes:


              *-----------L-----------*
              |                       |
        *-----F-----*           *-----R-----*
        |           |           |           |
      *-C-*       *-I-*       *-O-*       *-U-*
      |   |       |   |       |   |       |   |
    *-B   D-*   *-H   J-*   *-N   P*-   *-T   V-*
    |       |   |       |   |       |   |       |
    A       E   G       K   M       Q   S       W                     */

    if (maxBal == 11)
      {
        GBSNode a = fpoint;
        GBSNode b = a.rightChild();
        GBSNode c = b.rightChild();
        GBSNode d = c.rightChild();
        GBSNode e = d.rightChild();
        GBSNode f = e.rightChild();
        GBSNode g = f.rightChild();
        GBSNode h = g.rightChild();
        GBSNode i = h.rightChild();
        f.setLeftChild(c);
        f.setRightChild(i);
        c.setLeftChild(b);
        b.setLeftChild(a);
        b.clearRightChild();
        a.clearRightChild();
        e.clearRightChild();
        i.setLeftChild(h);
        h.setLeftChild(g);
        h.clearRightChild();
        g.clearRightChild();
        if (bparent.rightChild() == a)
          bparent.setRightChild(f);
        else
          bparent.setLeftChild(f);
      }
    else
      {
        if (maxBal != 14)
          error("fringeBalance12: maxBal != 14, maxBal = " + maxBal);
        GBSNode t0_top = stack.node(fpidx-3);
        GBSNode f = stack.node(fpidx-2);
        GBSNode j = fpoint;
        GBSNode k = j.rightChild();
        GBSNode l = k.rightChild();
        GBSNode m = l.rightChild();
        GBSNode n = m.rightChild();
        GBSNode o = n.rightChild();
        GBSNode p = o.rightChild();
        GBSNode q = p.rightChild();
        GBSNode r = q.rightChild();
        GBSNode s = r.rightChild();
        GBSNode t = s.rightChild();
        GBSNode u = t.rightChild();
        if (t0_top.rightChild() == f)
          t0_top.setRightChild(l);
        else
          t0_top.setLeftChild(l);
        l.setLeftChild(f);
        l.setRightChild(r);
        r.setLeftChild(o);
        r.setRightChild(u);
        o.setLeftChild(n);
        n.setLeftChild(m);
        n.clearRightChild();
        m.clearRightChild();
        q.clearRightChild();
        u.setLeftChild(t);
        t.setLeftChild(s);
        t.clearRightChild();
        s.clearRightChild();
        k.clearRightChild();
        if ((fpidx > 3) && (stack.balancePointIndex() > -1))
          {
            GBSNode qpoint = l;
            stack.setNode(fpidx-2, qpoint);
            GBSInsertHeight.singleInstance().balance(stack, qpoint);
          }
      }
  }

