public static String getJarVersionNumber() {
    Class clazz = SelendroidStandaloneDriver.class;
    String className = clazz.getSimpleName() + ".class";
    String classPath = clazz.getResource(className).toString();
    String version = "";

    if (!classPath.startsWith("jar")) {
      // Class not from JAR
      if(classPath.startsWith("file") && classPath.contains("target")) {
        try {
          version = getVersionFromPom(classPath.substring(5, classPath.lastIndexOf("target")));
        } catch (Exception e) {
          e.printStackTrace();
          return "";
        }
      } else return "dev";
    } else {
        try {
          version = getVersionFromManifest(classPath);
        } catch (IOException e){
          return "";
        }
    }
    return version;
  }

protected JMenuItem findMenu(AbstractCommand attachedCommand, List abstractButtons) {

        if (abstractButtons == null) {
            return null;
        }

        for (Iterator it = abstractButtons.iterator(); it.hasNext();) {
            AbstractButton button = (AbstractButton)it.next();
            if (button instanceof JMenuItem && attachedCommand.isAttached(button)) {
                it.remove();
                return (JMenuItem)button;
            }
        }
        return null;
    }

@SuppressWarnings("unchecked")
  public static Span parse(String text, Options options) {
    // store now for later =)
    //_now = options.getNow();

    // put the text into a normal format to ease scanning
    String normalizedText = Chronic.preNormalize(text);

    // get base tokens for each word
    List<Token> tokens = Chronic.baseTokenize(normalizedText);

    List<Class> optionScannerClasses = new LinkedList<Class>();
    optionScannerClasses.add(Repeater.class);
    for (Class optionScannerClass : optionScannerClasses) {
      try {
        tokens = (List<Token>) optionScannerClass.getMethod("scan", List.class, Options.class).invoke(null, tokens, options);
      }
      catch (Throwable e) {
        throw new RuntimeException("Failed to scan tokens.", e);
      }
    }

    List<Class> scannerClasses = new LinkedList<Class>();
    scannerClasses.add(Grabber.class);
    scannerClasses.add(Pointer.class);
    scannerClasses.add(Scalar.class);
    scannerClasses.add(Ordinal.class);
    scannerClasses.add(Separator.class);
    scannerClasses.add(TimeZone.class);
    for (Class scannerClass : scannerClasses) {
      try {
        tokens = (List<Token>) scannerClass.getMethod("scan", List.class, Options.class).invoke(null, tokens, options);
      }
      catch (Throwable e) {
        throw new RuntimeException("Failed to scan tokens.", e);
      }
    }

    List<Token> taggedTokens = new LinkedList<Token>();
    for (Token token : tokens) {
      if (token.isTagged()) {
        taggedTokens.add(token);
      }
    }
    tokens = taggedTokens;

    if (options.isDebug()) {
      System.out.println("Chronic.parse: " + tokens);
    }

    Span span = Handler.tokensToSpan(tokens, options);

    // guess a time within a span if required
    if (options.isGuess()) {
      span = guess(span);
    }

    return span;
  }

public long depass(final String password, final OutputStream os) throws IOException {
	  int offset = password.startsWith(ENC)?4:0;
	  final ByteArrayOutputStream baos = new ByteArrayOutputStream();
	  final ByteArrayInputStream bais =  new ByteArrayInputStream(password.getBytes(),offset,password.length()-offset);
	  exec(new AESExec() {
		@Override
		public void exec(AES aes) throws IOException {
			  CipherOutputStream cos = aes.outputStream(baos, false);
			  decode(bais,cos);
			  cos.close(); // flush
		}
	  });
	  byte[] bytes = baos.toByteArray();
	  DataInputStream dis = new DataInputStream(new ByteArrayInputStream(bytes));
	  long time;
	  if(this.getClass().getSimpleName().startsWith("base64")) { // don't expose randomization
		  os.write(bytes);
		  time = 0L;
	  } else {
		  int start=0;
		  for(int i=0;i<3;++i) {
			  start+=Math.abs(dis.readByte());
		  }
		  start%=0x7;
		  for(int i=0;i<start;++i) {
			  dis.readByte();
		  }
		  time = (dis.readInt() & 0xFFFF)|(System.currentTimeMillis()&0xFFFF0000);
		  int minlength = dis.readByte();
		  if(minlength<0x9){
			DataOutputStream dos = new DataOutputStream(os);
			for(int i=0;i<minlength;++i) {
				dis.readByte();
				dos.writeByte(dis.readByte());
			}
		  } else {
			  int pre =((Byte.SIZE*3+Integer.SIZE+Byte.SIZE)/Byte.SIZE)+start; 
			  os.write(bytes, pre, bytes.length-pre);
		  }
	  }
	  return time;
  }

public static <T, R> Function1<T, R> memoizeFunction(final Function<T, R> fn, final Cacheable<R> cache) {
        LazyImmutable<R> nullR = LazyImmutable.def();
        return t -> t==null? nullR.computeIfAbsent(()->fn.apply(null)) : (R)cache.soften()
                         .computeIfAbsent(t, (Function) fn);
    }

