public static long getServerId() {
		String ipAddress = getLocalHostAddress();
		try {
			long result = 0;
			String[] array = ipAddress.split("\\.");
			for(String s : array){
				long i = Long.parseLong(s);
				result = 256 * result + i;
			}
			return result;
		} catch (Exception e) {
			return ipAddress.hashCode();
		}
	}

