@Override
  public State getFinalState() {
    ConstructState state = new ConstructState();
    if (this.converter != null) {
      state.addConstructState(Constructs.CONVERTER, new ConstructState(this.converter.getFinalState()));
    }
    if (this.rowLevelPolicyChecker != null) {
      state.addConstructState(Constructs.ROW_QUALITY_CHECKER,
          new ConstructState(this.rowLevelPolicyChecker.getFinalState()));
    }
    if (this.writer.isPresent() && this.writer.get() instanceof FinalState) {
      state.addConstructState(Constructs.WRITER, new ConstructState(((FinalState) this.writer.get()).getFinalState()));
    }
    return state;
  }

public void loadModel(final GVRSceneObject model, final GVRResourceVolume volume, final EnumSet<GVRImportSettings> settings, final GVRScene scene)
    {
        Threads.spawn(new Runnable()
        {
            public void run()
            {
                String filePath = volume.getFileName();
                AssetRequest assetRequest = new AssetRequest(model, volume, scene, null, false);
                String ext = filePath.substring(filePath.length() - 3).toLowerCase();

                model.setName(assetRequest.getBaseName());
                assetRequest.setImportSettings(settings);
                try
                {
                    if (ext.equals("x3d"))
                    {
                        loadX3DModel(assetRequest, model);
                    }
                    else
                    {
                        loadJassimpModel(assetRequest, model);
                    }
                }
                catch (IOException ex)
                {
                    // onModelError is generated in this case.
                }
            }
        });
    }

public static FirefoxProfile getFirefoxProfile(Map<String, Object> profile) {
        FirefoxProfile fxProfile = new FirefoxProfile();
        if (profile != null) {
            for (Map.Entry<String, Object> profileEntry : profile.entrySet()) {
                String key = profileEntry.getKey();
                Object value = profileEntry.getValue();
                if (value instanceof Boolean) {
                    fxProfile.setPreference(key, (Boolean) value);
                } else if (value instanceof Integer) {
                    fxProfile.setPreference(key, (Integer) value);
                } else if (value == null) {
                    fxProfile.setPreference(key, null);
                } else {
                    fxProfile.setPreference(key, value.toString());
                }
            }
        }
        return fxProfile;
    }

