  public void init()
    throws ConfigException
  {
    if (_classDir == null) {
      throw new ConfigException(L.l("'path' is a required attribute of <compiling-loader>."));
    }

    String scheme = _classDir.getScheme();

    if (scheme != null
        && ! scheme.equals("memory")
        && ! scheme.equals("error")) {
      try {
        _classDir.mkdirs();
      } catch (IOException e) {
        log.log(Level.FINE, e.toString(), e);
      }

      try {
        _codeSource = new CodeSource(new URL(_classDir.getURL()), (Certificate []) null);
      } catch (Exception e) {
        log.log(Level.FINE, e.toString(), e);
      }
    }

    super.init();

    getClassLoader().addURL(_classDir);
  }

public static <T> Paging<T> flattenPaging(Collection<Paging<T>> collectionOfPaging)
	{
		if (collectionOfPaging == null || collectionOfPaging.isEmpty())
			return null;

		PageCriteria pageCriteria = null;
		// get first page criteria
		Paging<T> firstPaging = collectionOfPaging.iterator().next();

		if (firstPaging != null)
			pageCriteria = firstPaging.getPageCriteria();

		return flattenPaging(collectionOfPaging, pageCriteria, null, null);

	}

