public static int match(Locale locale, Locale targetLocale) {
        if (locale == null) {
            return -1;
        }
        if (locale.getLanguage().equals(targetLocale.getLanguage())) {
            if (locale.getCountry().equals(targetLocale.getCountry())) {
                return 3;
            } else if (targetLocale.getCountry().isEmpty()) {
                return 2;
            } else {
                return 0;
            }
        } else if (targetLocale.getCountry().isEmpty() || targetLocale.getLanguage().isEmpty()) {
            return 1;
        } else {
            return 0;
        }
    }

public void reInitInlineEditing() {

        removeEditButtonsPositionTimer();
        if ((m_targetContainers == null) || getData().isUseClassicEditor()) {
            // if the target containers are not initialized yet or classic editor is set, don't do anything
            return;
        }
        if (isGroupcontainerEditing()) {
            for (Widget element : m_groupEditor.getGroupContainerWidget()) {
                if (((element instanceof CmsContainerPageElementPanel)
                    && isInlineEditable(
                        (CmsContainerPageElementPanel)element,
                        m_groupEditor.getGroupContainerWidget()))) {
                    ((CmsContainerPageElementPanel)element).initInlineEditor(this);
                }
            }
        } else {
            for (CmsContainerPageContainer container : m_targetContainers.values()) {
                // first remove inline editors
                for (Widget element : container) {
                    if ((element instanceof CmsContainerPageElementPanel)) {
                        ((CmsContainerPageElementPanel)element).removeInlineEditor();
                    }
                }

                // add inline editors only on suitable elements
                if (isContainerEditable(container) && matchesCurrentEditLevel(container)) {
                    for (Widget element : container) {
                        if ((element instanceof CmsContainerPageElementPanel)
                            && isInlineEditable((CmsContainerPageElementPanel)element, container)) {
                            ((CmsContainerPageElementPanel)element).initInlineEditor(this);
                        }
                    }
                }
            }
        }
    }

protected void loadOptionalExecutor(final String executorBinder) {
        try {
            final Method bindExecutor = RepositoryModule.class.getDeclaredMethod("bindExecutor", Class.class);
            bindExecutor.setAccessible(true);
            try {
                Class.forName(executorBinder)
                        .getConstructor(RepositoryModule.class, Method.class)
                        .newInstance(this, bindExecutor);
            } finally {
                bindExecutor.setAccessible(false);
            }
        } catch (Exception ignore) {
            if (logger.isTraceEnabled()) {
                logger.trace("Failed to process executor loader " + executorBinder, ignore);
            }
        }
    }

@Override
  public ISerializable afterDeserialization(ISerializable deserializedObject, Object serializationData)
      throws DDFException {

    try {
      if (!Strings.isNullOrEmpty(mUnitTypeName)) {
        mUnitType = Class.forName(mUnitTypeName);
      }

      if (mData != null) {
        this.setList(mData, mUnitType);

        // See if we need to "unwrap" this object and return the wrapped object instead
        JsonElement deserializedWrappedObject = (serializationData instanceof JsonObject ? //
            ((JsonObject) serializationData).get("mData")
            : null);

        deserializedObject = BasicPersistible.unwrapDeserializedObject(mData, deserializedObject,
            (JsonElement) deserializedWrappedObject);
      }

      return super.afterDeserialization(deserializedObject, serializationData);

    } catch (Exception e) {
      if (e instanceof DDFException) throw (DDFException) e;
      else throw new DDFException(e);
    }
  }

