public void forward(HttpServletRequest request,
			HttpServletResponse response, final String target)
			throws ServletException, IOException {
		if (target.startsWith("/WEB-INF/classes")
				|| target.startsWith("/WEB-INF/lib")
				|| target.matches("^/WEB-INF/.+\\.xml")) {
			throw new IOException("Not allowed");
		}
		this.contentJsp = target;
		this.originalRequestURL = request.getRequestURL().toString();
		request.setAttribute(FERRET_NAME, this);
		RequestDispatcher dispatcher = request.getRequestDispatcher(target);
		if(dispatcher == null) {
			throw new IOException("No dispatcher for " + target);
		}

		dispatcher.forward(request, response);
	}

public void addIndividual(org.opencb.biodata.models.metadata.Individual individual, String studyId) {
        // Sanity check
        if (individual == null || StringUtils.isEmpty(individual.getId())) {
            logger.error("Individual (or its ID) is null or empty.");
            return;
        }

        VariantStudyMetadata variantStudyMetadata = getVariantStudyMetadata(studyId);
        if (variantStudyMetadata == null) {
            logger.error("Study not found. Check your study ID: '{}'", studyId);
            return;
        }
        if (variantStudyMetadata.getIndividuals() == null) {
            variantStudyMetadata.setIndividuals(new ArrayList<>());
        }
        for (org.opencb.biodata.models.metadata.Individual indi: variantStudyMetadata.getIndividuals()) {
            if (indi.getId() != null && indi.getId().equals(individual.getId())) {
                logger.error("Individual with id '{}' already exists in study '{}'", individual.getId(),
                        studyId);
                return;
            }
        }
        variantStudyMetadata.getIndividuals().add(individual);
    }

public void align(Structure s1, String chainId1, Structure s2,
			String chainId2, StrucAligParameters params)
			throws StructureException {
		reset();
		this.params = params;

		Chain c1 = s1.getPolyChainByPDB(chainId1);
		Chain c2 = s2.getPolyChainByPDB(chainId2);

		Structure s3 = new StructureImpl();
		s3.addChain(c1);

		Structure s4 = new StructureImpl();
		s4.addChain(c2);

		Atom[] ca1 = getAlignmentAtoms(s3);
		Atom[] ca2 = getAlignmentAtoms(s4);

		notifyStartingAlignment(s1.getName(), ca1, s2.getName(), ca2);
		align(ca1, ca2, params);
	}

private long getNextAlignedWindowTs(long startTs, long endTs) {
        long nextTs = windowManager.getEarliestEventTs(startTs, endTs);
        if (nextTs == Long.MAX_VALUE || (nextTs % slidingIntervalMs == 0)) {
            return nextTs;
        }
        return nextTs + (slidingIntervalMs - (nextTs % slidingIntervalMs));
    }

public Observable<ServiceResponse<List<IntentsSuggestionExample>>> getIntentSuggestionsWithServiceResponseAsync(UUID appId, String versionId, UUID intentId, Integer take) {
        if (this.client.endpoint() == null) {
            throw new IllegalArgumentException("Parameter this.client.endpoint() is required and cannot be null.");
        }
        if (appId == null) {
            throw new IllegalArgumentException("Parameter appId is required and cannot be null.");
        }
        if (versionId == null) {
            throw new IllegalArgumentException("Parameter versionId is required and cannot be null.");
        }
        if (intentId == null) {
            throw new IllegalArgumentException("Parameter intentId is required and cannot be null.");
        }
        String parameterizedHost = Joiner.on(", ").join("{Endpoint}", this.client.endpoint());
        return service.getIntentSuggestions(appId, versionId, intentId, take, this.client.acceptLanguage(), parameterizedHost, this.client.userAgent())
            .flatMap(new Func1<Response<ResponseBody>, Observable<ServiceResponse<List<IntentsSuggestionExample>>>>() {
                @Override
                public Observable<ServiceResponse<List<IntentsSuggestionExample>>> call(Response<ResponseBody> response) {
                    try {
                        ServiceResponse<List<IntentsSuggestionExample>> clientResponse = getIntentSuggestionsDelegate(response);
                        return Observable.just(clientResponse);
                    } catch (Throwable t) {
                        return Observable.error(t);
                    }
                }
            });
    }

