@Override
    public WSStatistic getStatistic(int dataId) {
        ArrayList members = copyStatistics();
        if (members == null || members.size() <= 0)
            return null;

        int sz = members.size();
        for (int i = 0; i < sz; i++) {
            StatisticImpl data = (StatisticImpl) members.get(i);
            if (data != null && data.getId() == dataId) {
                return data;
            }
        }
        return null;
    }

