function(message, privateKey, cb = null)
	{
        var result
        try {
            result = secp256k1.sign(ethUtils.sha3(message), privateKey)
        }
        catch (err){
            result = err
        }
        if(isFunction(cb)){
            if(result instanceof Error){
                return cb(result)
            } else {
                return cb(null, result)
            }
        }
        else {
            return result
        }
	}

