function getBBox(element, window) {
  const rect = element.getBoundingClientRect(),
    bBox = {left: rect.left, top: rect.top,
      right: rect.right, bottom: rect.bottom, width: rect.width, height: rect.height};
  if (window) {
    bBox.left += window.pageXOffset;
    bBox.right += window.pageXOffset;
    bBox.top += window.pageYOffset;
    bBox.bottom += window.pageYOffset;
  }
  return bBox;
}

function buildRequestor(clientOptions) {
  if(clientOptions.requestor) return clientOptions.requestor;

  var requestorConfig =
    _.pick(clientOptions, 'maxRetryDurationSeconds', 'calcRetryBackoff');

  if(requestorConfig.maxRetryDurationSeconds)
    requestorConfig.maxRetryDurationMillis = requestorConfig.maxRetryDurationSeconds * 1000;

  requestorConfig.logger = buildLogger(clientOptions);

  return require('./lib/utils/httpRequestor.js')
    .create(requestorConfig);
}

function checkEmail(msg, node) {
                if (node.protocol === 'POP3') {
                    checkPOP3(msg);
                } else if (node.protocol === 'IMAP') {
                    console.log('Inside checkEmail');
                    imap = new Imap({
                        user: node.userid,
                        password: node.password,
                        host: node.server,
                        port: node.port,
                        tls: node.useSSL,
                        tlsOptions: {rejectUnauthorized: false},
                        connTimeout: (node.repeat - 10),
                        authTimeout: (node.repeat - 10),
                    });

                    imap.on('error', function(err) {
                        if (err.errno !== 'ECONNRESET') {
                            node.log(err);
                            node.status({fill: 'red', shape: 'ring', text: 'email.status.connecterror'});
                        }
                    });

                    checkIMAP(msg, node.attachment);
                }
            }

