function makeTheCall(api, apiName, apiCall, fn) {
  request(apiCall, function(error, response, body) {
    if (error) {
      return fn('Error making API call to get ' + apiName + ' ' + resource +
        ': ' + error);
    } else if (response.statusCode == 200) {
      return fn(null, JSON.parse(body));
    } else {
      return fn('Unexpected status code for request to get '+
        apiCall + ': ' + response.statusCode);
    }
  });
}

function(node) {
				var fileClient = this.fileClient;
				if (node.Location === this.SEPARATOR) {
					return this.SEPARATOR;
				}
				var path = this.SEPARATOR + fileClient.fileServiceName(node.Location);
				var parents = node.Parents;
				if (parents) {
					path += this.SEPARATOR;
					for (var i = parents.length; --i >= 0 ;){
						path += parents[i].Name; 
						path += this.SEPARATOR;
					}
					path += node.Name;
				}
				if (node.Directory) {
					path += this.SEPARATOR;
				}
				return path;
			}

function handle() {
  var args = _.toArray(arguments);
  var fn = args.shift();
  var result = fn.apply(this, args);
  if (result instanceof Promise) {
    return result;
  } else {
    return Promise.resolve(result);
  }
}

