function checkStanza(hubClient, stanza, fields, author, opt_sigValue) {
  var sig = opt_sigValue === undefined ? stanza.sig : opt_sigValue;
  if (!sig) {
    throw new errors.AuthenticationError('No `sig` field in stanza');
  }
  if (!stanza.updatedAt || typeof(stanza.updatedAt) != 'number') {
    throw new errors.AuthenticationError('Invalid `updatedAt` field in stanza');
  }
  return hubClient.getUserProfile(author, stanza.updatedAt)
    .then(function(userProfile) {
      var verifier = ursa.createVerifier('sha1');
      updateWithFields(verifier, stanza, fields);
      var pubkeyStr = userProfile.pubkey;
      var pubkey = ursa.createPublicKey(pubkeyStr);
      var ok = verifier.verify(pubkey, stanza.sig, 'base64');
      if (ok) {
        return true;
      }
      debug('First verification failed', author);
      // The signatures do not match.  Refetch the author's profile directly
      // from the hub, then try again.
      if (Date.now() - userProfile.syncedAt < MIN_ENTITY_RESYNC_MS) {
        debug('Not refetching user profile', author);
        return false;
      }
      return hubClient.getUserProfileFromHub(author, stanza.updatedAt)
        .then(function(userProfile) {
          // The pubkeys are still the same, so don't bother re-checking.
          if (userProfile.pubkey == pubkeyStr) {
            debug('Pubkeys identical, not reverifying', author);
            return false;
          }
          // The pubkeys are different, so perhaps that's why the first check
          // failed.
          var pubkey = ursa.createPublicKey(userProfile.pubkey);
          return verifier.verify(userProfile.pubkey, sig, 'base64');
        })
    })
    .catch(errors.NotFoundError, function(err) {
      throw new errors.AuthenticationError(
          'No such user registered with the Hub: ' + author);
    })
    .then(function(ok) {
      if (!ok) {
        throw new errors.AuthenticationError('Stanza signatures do not match for user ' + author);
      }
      return ok;
    });
}

function multipart (req,options) {
    options = options || {};

    return new Promise((resolve,reject)=>{
        if (req._body) return resolve({no:200,msg:"已经解析"});
        req.body = req.body || {};
        req.files = req.files || {};

        // ignore GET
        if ('GET' === req.method || 'HEAD' === req.method) return next();

        // check Content-Type
        if (!typeis(req, 'multipart/form-data')) return resolve({no:404,msg:"没有包含文件"});

        // flag as parsed
        req._body = true;

        // parse
        var form = new multiparty.Form(options);
        var data = {};
        var files = {};//
        var done = false;

        function ondata(name, val, data){
            if (Array.isArray(data[name])) {
                data[name].push(val);
            } else if (data[name]) {
                data[name] = [data[name], val];
            } else {
                data[name] = val;
            }
        }

        form.on('field', function(name, val){
            ondata(name, val, data);
        });

        form.on('file', function(name, val){
            val.name = val.originalFilename;
            val.type = val.headers['content-type'] || null;
            ondata(name, val, files);//存放在files的东西转移到data里面,统一放到req.body中
        });

        form.on('error', function(err){
            if (done) return;

            done = true;
            // err.status = 400;

            if (!req.readable) return resolve({no:500,msg:err});

            req.resume();
            onFinished(req, function(){
                resolve({no:500,msg:err});
            });
        });

        form.on('close', function() {
            if (done) return;

            done = true;

            try {
                data = Object.assign(data, files);
                req.body = qs.parse(data,{ allowDots: true });
                req.files = qs.parse(files, { allowDots: true });
                resolve({no:200});
            } catch (err) {
                resolve({no:500,msg:err})
            }
        });

        form.parse(req);
    })
}

function findNode(name, root) {
        var i, stack, node;
        if (root === null || root === undefined) { return null; }
        stack = [root];
        while (stack.length > 0) {
            node = stack.pop();
            if (node.name === name) {
                return node;
            }
            for (i = node.children.length - 1; i >= 0; i -= 1) {
                stack.push(node.children[i]);
            }
        }
        return null;
    }

function addStepToBlock(that, block, stepId, stageId, positions) {
        var stepInBlock;
        // Add step, if not already added.
        if (block.hasItem(stepId)) return false;

        stepInBlock = {
            type: stageId,
            item: stepId,
            id: stepId
        };

        if (isDefaultStep(that.steps[stepId])) {
            makeDefaultStep(stepInBlock);
        }
        block.add(stepInBlock, positions);
        return true;
    }

function compile(options) {
    options = options || {};
    var fs = require('fs');
    var content = fs.readFileSync(options.indexFile || INDEX_FILE, 'utf8');
    // 插入同步数据的注入点
    content = content.replace('</head>', '<script>window.__rebas__ = ${rebas}</script>\n</head>');

    var etpl = require('etpl');
    etpl = new etpl.Engine({defaultFilter: 'raw'});
    return etpl.compile(content);
}

function expression(rbp, initial) {

// rbp is the right binding power.
// initial indicates that this is the first expression of a statement.

        var left;
        if (next_token.id === '(end)') {
            stop('unexpected_a', token, next_token.id);
        }
        advance();
        if (option.safe && scope[token.string] &&
                scope[token.string] === global_scope[token.string] &&
                (next_token.id !== '(' && next_token.id !== '.')) {
            warn('adsafe_a', token);
        }
        if (initial) {
            anonname = 'anonymous';
            funct['(verb)'] = token.string;
        }
        if (initial === true && token.fud) {
            left = token.fud();
        } else {
            if (token.nud) {
                left = token.nud();
            } else {
                if (next_token.id === '(number)' && token.id === '.') {
                    warn('leading_decimal_a', token, artifact());
                    advance();
                    return token;
                }
                stop('expected_identifier_a', token, token.id);
            }
            while (rbp < next_token.lbp) {
                advance();
                if (token.led) {
                    left = token.led(left);
                } else {
                    stop('expected_operator_a', token, token.id);
                }
            }
        }
        return left;
    }

function parsebody(body){
