		if (res.statusCode !== 201) {
			self.emit('error', new Error('Unexpected response code: ' + res.statusCode));
		}
	});
	req.on('error', function (error) {
		/**
		 * Emitted when an error occurs.
		 * @event Client#error
		 * @param {Error} error The error object.
		 */
		self.emit('error', error);
