func BuildReaderProof(r io.Reader, h hash.Hash, segmentSize int, index uint64) (root []byte, proofSet [][]byte, numLeaves uint64, err error) {
	tree := New(h)
	err = tree.SetIndex(index)
	if err != nil {
		// This code should be unreachable - SetIndex will only return an error
		// if the tree is not empty, and yet the tree should be empty at this
		// point.
		panic(err)
	}
	err = tree.ReadAll(r, segmentSize)
	if err != nil {
		return
	}
	root, proofSet, _, numLeaves = tree.Prove()
	if len(proofSet) == 0 {
		err = errors.New("index was not reached while creating proof")
		return
	}
	return
}

func (c LogConfig) Apply() error {
	logger := log.DefaultLogger()

	filename := c.Filename
	if len(*logFilename) > 0 {
		filename = *logFilename
	}
	if v := viper.GetString("log.file"); len(v) > 0 {
		filename = v
	}
	if len(filename) > 0 && !ignoreLogFilename {
		abspath, err := filepath.Abs(filename)
		if err != nil {
			return err
		}
		w, err := openLogFile(abspath)
		if err != nil {
			return err
		}
		logger.SetOutput(w)
	}

	level := c.Level
	if len(*logLevel) > 0 {
		level = *logLevel
	}
	if v := viper.GetString("log.level"); len(v) > 0 {
		level = v
	}
	if len(level) == 0 {
		level = "info"
	}
	err := logger.SetThresholdByName(level)
	if err != nil {
		return err
	}

	format := c.Format
	if len(*logFormat) > 0 {
		format = *logFormat
	}
	if v := viper.GetString("log.format"); len(v) > 0 {
		format = v
	}
	switch format {
	case "", "plain":
		logger.SetFormatter(log.PlainFormat{})
	case "logfmt":
		logger.SetFormatter(log.Logfmt{})
	case "json":
		logger.SetFormatter(log.JSONFormat{})
	default:
		return errors.New("invalid format: " + format)
	}

	return nil
}

