func (axp *TxPool) Close() {
	axp.ticks.Stop()
	for _, v := range axp.activePool.GetOutdated(time.Duration(0), "for closing") {
		conn := v.(*TxConnection)
		log.Warningf("killing transaction for shutdown: %s", conn.Format(nil))
		tabletenv.InternalErrors.Add("StrayTransactions", 1)
		conn.Close()
		conn.conclude(TxClose, "pool closed")
	}
	axp.conns.Close()
	axp.foundRowsPool.Close()
}

func (p *pool) SelectAndKill(id, reason string) {
	rp, err := p.Remove(p.plugins.Values(), id)
	if err != nil {
		log.WithFields(log.Fields{
			"_block": "SelectAndKill",
			"taskID": id,
			"reason": reason,
		}).Error(err)
		return
	}
	if err := rp.Stop(reason); err != nil {
		log.WithFields(log.Fields{
			"_block": "SelectAndKill",
			"taskID": id,
			"reason": reason,
		}).Error(err)
	}
	if err := rp.Kill(reason); err != nil {
		log.WithFields(log.Fields{
			"_block": "SelectAndKill",
			"taskID": id,
			"reason": reason,
		}).Error(err)
	}
	p.remove(rp.ID())
}

