func (gen *Generator) GenerateNewScope(expressions []Sexp) error {
	size := len(expressions)
	oldtail := gen.Tail
	gen.Tail = false
	if size == 0 {
		return nil
		//return NoExpressionsFound
	}

	gen.AddInstruction(AddScopeInstr{Name: "newScope"})
	for _, expr := range expressions[:size-1] {
		err := gen.Generate(expr)
		if err != nil {
			return err
		}
		// insert pops after all but the last instruction
		// that way the stack remains clean... Q: how does this extra popping not mess up the expressions?
		gen.AddInstruction(PopInstr(0))
	}
	gen.Tail = oldtail
	err := gen.Generate(expressions[size-1])
	if err != nil {
		return err
	}
	gen.AddInstruction(RemoveScopeInstr{})
	return nil
}

func (a *ErrorList) AppendWithPrefix(err error, prefix string) {
	switch err := err.(type) {
	case ErrorList:
		for i := range err {
			*a = append(*a, fmt.Errorf("%s%s", prefix, err[i]))
		}
	default:
		*a = append(*a, fmt.Errorf("%s%s", prefix, err))
	}
}

func (env Env) Inputs() []Input {
	(&env).defaults()

	// This is how the inputs array is constructed:
	// 0, 3, -99, -99, -- starting level, num segments, releaseNode, loopNode
	// 1, 0.1, 5, 4, -- first segment: level, time, curve type, curvature
	// 0.5, 1, 5, -4, -- second segment: level, time, curve type, curvature
	// 0, 0.2, 5, 4 -- and so on
	var (
		curvesArray = env.curvesArray()
		lc          = len(curvesArray)
		lt          = len(env.Times)
	)
	if lc != lt {
		panic(fmt.Errorf("%d curve types != %d times", lc, lt))
	}

	var (
		numSegments = len(env.Levels) - 1
		arr         = make([]Input, 4*(numSegments+1))
	)
	arr[0] = env.Levels[0]
	arr[1] = C(numSegments)
	arr[2] = env.ReleaseNode
	arr[3] = env.LoopNode
	for i, t := range env.Times {
		arr[(4*i)+4] = env.Levels[i+1]
		arr[(4*i)+5] = t
		arr[(4*i)+6] = shapeNumber(curvesArray[i])
		arr[(4*i)+7] = curveValue(curvesArray[i])
	}
	return arr
}

