func CreditCardNum(vendor string) string {
	if vendor != "" {
		vendor = strings.ToLower(vendor)
	} else {
		var vendors []string
		for v := range creditCards {
			vendors = append(vendors, v)
		}
		vendor = vendors[r.Intn(len(vendors))]
	}
	card := creditCards[vendor]
	prefix := strconv.Itoa(card.prefixes[r.Intn(len(card.prefixes))])
	num := []rune(prefix)
	for i := 0; i < card.length-len(prefix); i++ {
		num = append(num, genCCDigit(num))
	}
	return string(num)
}

func ToFloat64(v Value) (float64, error) {
	num, err := newNumeric(v)
	if err != nil {
		return 0, err
	}
	switch num.typ {
	case Int64:
		return float64(num.ival), nil
	case Uint64:
		return float64(num.uval), nil
	case Float64:
		return num.fval, nil
	}
	panic("unreachable")
}

